193	int bk7258_gpio_config_input(unsigned int pin,
194	                             enum bk7258_gpio_pull_e pull)
195	{
196	  irqstate_t flags;
197	  uint32_t regval;
198	
199	  if (!bk7258_gpio_valid(pin) || pull < BK7258_GPIO_PULL_NONE ||
200	      pull > BK7258_GPIO_PULL_DOWN)
201	    {
202	      return -EINVAL;
203	    }
204	
205	  flags = enter_critical_section();
206	  bk7258_gpio_select_func_locked(pin);
207	
208	  regval  = getreg32(BK7258_GPIO_CFG(pin));
209	  regval &= ~(BK7258_GPIO_CFG_MODE_MASK |
210	              BK7258_GPIO_CFG_PULL_MASK |
211	              BK7258_GPIO_CFG_SECOND_FUNC);
212	  regval |= BK7258_GPIO_CFG_MODE_INPUT;
213	
214	  switch (pull)
215	    {
216	      case BK7258_GPIO_PULL_UP:
217	        regval |= BK7258_GPIO_CFG_PULL_UP;
218	        break;
219	
220	      case BK7258_GPIO_PULL_DOWN:
221	        regval |= BK7258_GPIO_CFG_PULL_DOWN;
222	        break;
223	
224	      default:
225	        break;
226	    }
227	
228	  putreg32(regval, BK7258_GPIO_CFG(pin));
229	  leave_critical_section(flags);
230	  return OK;
231	}
232	
233	int bk7258_gpio_config_output(unsigned int pin, bool initial)
234	{
235	  irqstate_t flags;
236	  uint32_t regval;
237	
238	  if (!bk7258_gpio_valid(pin))
239	    {
240	      return -EINVAL;
241	    }
242	
243	  flags = enter_critical_section();
244	  bk7258_gpio_select_func_locked(pin);
245	
246	  /* Program the output latch while the output driver is still disabled, then
247	   * switch the pin to output mode.  Keeping both writes in one critical
248	   * section prevents another register update from introducing a glitch.
249	   */
250	
251	  regval = getreg32(BK7258_GPIO_CFG(pin));
252	  if (initial)
253	    {
254	      regval |= BK7258_GPIO_CFG_OUTPUT;
255	    }
256	  else
257	    {
258	      regval &= ~BK7258_GPIO_CFG_OUTPUT;
259	    }
260	
261	  putreg32(regval, BK7258_GPIO_CFG(pin));
262	
263	  regval &= ~(BK7258_GPIO_CFG_MODE_MASK |
264	              BK7258_GPIO_CFG_PULL_MASK |
265	              BK7258_GPIO_CFG_SECOND_FUNC);
266	  regval |= BK7258_GPIO_CFG_MODE_OUTPUT;
267	  putreg32(regval, BK7258_GPIO_CFG(pin));
268	  leave_critical_section(flags);
269	  return OK;
270	}
