209	
210	  switch (mode)
211	    {
212	      case SPIDEV_MODE0: /* CPOL=0 CPHA=0 */
213	        priv->hw->ctrl.cpol = 0;
214	        priv->hw->ctrl.cpha = 0;
215	        break;
216	
217	      case SPIDEV_MODE1: /* CPOL=0 CPHA=1 */
218	        priv->hw->ctrl.cpol = 0;
219	        priv->hw->ctrl.cpha = 1;
220	        break;
221	
222	      case SPIDEV_MODE2: /* CPOL=1 CPHA=0 */
223	        priv->hw->ctrl.cpol = 1;
224	        priv->hw->ctrl.cpha = 0;
225	        break;
226	
227	      case SPIDEV_MODE3: /* CPOL=1 CPHA=1 */
228	        priv->hw->ctrl.cpol = 1;
229	        priv->hw->ctrl.cpha = 1;
230	        break;
231	
232	      default:
233	        printf("SPI1: ERROR invalid mode %d\n", mode);
234	        return;
235	    }
236	
237	  priv->mode = mode;
