329	/****************************************************************************
330	 * Name: jd9853_cmddata
331	 *
332	 * Description:
333	 *   Send a command and a series of data to the driver.
334	 *
335	 ****************************************************************************/
336	
337	static void jd9853_cmddata(FAR struct jd9853_dev_s *dev, uint8_t cmd,
338	                                      const uint8_t *data, int len)
339	{
340	  jd9853_select(dev->spi, 8);
341	  SPI_CMDDATA(dev->spi, SPIDEV_DISPLAY(0), true);
342	  SPI_SEND(dev->spi, cmd);
343	  SPI_CMDDATA(dev->spi, SPIDEV_DISPLAY(0), false);
344	  SPI_SNDBLOCK(dev->spi, data, len);

160	  /* Configure the bit-bang GPIO pins */
161	
162	  bk7258_gpio_config_output(BOARD_LCD_SCL_PIN, false);
163	  bk7258_gpio_config_output(BOARD_LCD_SDA_PIN, false);
164	  bk7258_gpio_config_output(BOARD_LCD_CS_PIN, true);
165	  bk7258_gpio_config_output(BOARD_LCD_DC_PIN, false);
166	
167	  /* Idle levels: CS de-asserted high, D/C driven low until a command or
168	   * data transfer begins.
169	   */
170	
171	  bk7258_gpio_write(BOARD_LCD_CS_PIN, true);
172	  bk7258_gpio_write(BOARD_LCD_DC_PIN, false);
173	  bk7258_gpio_write(BOARD_LCD_SCL_PIN, false);
174	
175	  return spi_create_bitbang(&g_spiops, NULL);
176	}
