{
	if(gpio_hal_map_check(hal, gpio_id)) {
		HAL_LOGW("gpio has map\r\n");
		return BK_ERR_GPIO_INTERNAL_USED;
	}

	gpio_ll_set_mode(hal->hw, gpio_id, config);

