27	/* spi_clk(more than 1M) support list when source_clk = XTAL_26M
28	 * sort the numbers from largest to smallest, otherwize binary_search will not work
29	 */
30	static const uint32_t s_spi_clk_list[] = {
31		26000000, /**< DIV1 */
32		13000000, /**< DIV2 */
33		6500000,  /**< DIV4 */
34		5200000,  /**< DIV5 */
35		3250000,  /**< DIV8 */
36		2600000,  /**< DIV10 */
37		2000000,  /**< DIV13 */
38		1625000,  /**< DIV16 */
39		1300000,  /**< DIV20 */
40		1040000,  /**< DIV25 */
41		1000000,  /**< DIV26 */
42	};
