71	/* 1. bit_width, clk_rate, cpol, cpha, master/slave, 4line, int_level=0, rxovf_en=1, txudf_en=1
72	 * 2. if 4 wire mode, enable sla_release_int_en, clear slv_release_int
73	 * 3. set rx_callback, tx_need_write_callback, tx_finish_callback
74	 * 4. enable spi, bit[23] spi_en
75	 * 5. if need clk_rate more than 26M, need close i2s to avoid conflict about APLL 98M clock
76	 */
77	bk_err_t spi_hal_configure(spi_hal_t *hal, const spi_config_t *config)
78	{
79		spi_ll_enable_tx_underflow_int(hal->hw);
80		spi_ll_enable_rx_overflow_int(hal->hw);
81		spi_ll_disable_tx_fifo_int(hal->hw);
82		spi_ll_enable_rx_fifo_int(hal->hw);
83	
84		spi_hal_set_baud_rate(hal, config->baud_rate);
85	#if (CONFIG_SPI_BYTE_INTERVAL)
86		spi_hal_set_byte_interval(hal, config->byte_interval);
87	#endif
88	
89		spi_ll_set_bit_width(hal->hw, config->bit_width);
90		spi_ll_set_first_bit(hal->hw, config->bit_order);
91		spi_ll_set_cpol(hal->hw, config->polarity);
92		spi_ll_set_cpha(hal->hw, config->phase);
93		if (config->role == SPI_ROLE_SLAVE) {
94			spi_ll_set_role_slave(hal->hw);
95		} else {
96			spi_ll_set_role_master(hal->hw);
97		}
98		spi_ll_set_wire_mode(hal->hw, config->wire_mode);
99		if (config->wire_mode == SPI_4WIRE_MODE) {
100			spi_ll_enable_slave_release_int(hal->hw);
101		} else {
102			spi_ll_disable_slave_release_int(hal->hw);
103		}
104		spi_ll_enable_tx_finish_int(hal->hw);
105		spi_ll_enable_rx_finish_int(hal->hw);
106		spi_ll_clear_int_status(hal->hw);
107	
108		return BK_OK;
109	}
