294	/* 1. power up spi
295	 * 2. set clk
296	 * 3. set gpio as spi
297	 * 4. icu enable interrupt
298	 */
299	static bk_err_t spi_id_init_common(spi_id_t id)
300	{
301		int ret = 0;
302	
303	#if (CONFIG_SYSTEM_CTRL)
304		spi_clock_enable(id);
305		spi_interrupt_enable(id);
306	#else
307		power_up_spi(id);
308		clk_set_spi_clk_26m(id);
309		icu_enable_spi_interrupt(id);
310	#endif
311		spi_init_gpio(id);
312	
313		if (s_spi[id].tx_sema == NULL) {
314			ret = rtos_init_semaphore(&(s_spi[id].tx_sema), 1);
315			BK_ASSERT(kNoErr == ret); /* ASSERT VERIFIED */
316		}
317		if (s_spi[id].rx_sema == NULL) {
318			ret = rtos_init_semaphore(&(s_spi[id].rx_sema), 1);
319			BK_ASSERT(kNoErr == ret); /* ASSERT VERIFIED */
320		}
321		s_spi[id].is_tx_blocked = false;
322		s_spi[id].is_sw_tx_finished = true;
323		s_spi[id].is_rx_blocked = false;
324		s_spi[id].id_init_bits |= BIT(id);
325	
326		return ret;
327	}
328	
329	static void spi_id_deinit_common(spi_id_t id)
330	{
331		spi_hal_stop_common(&s_spi[id].hal);
332	
333	#if (CONFIG_SYSTEM_CTRL)
334		spi_clock_disable(id);
335		spi_interrupt_disable(id);
336	#else
337		icu_disable_spi_interrupt(id);
338		power_down_spi(id);
339	#endif
340		rtos_deinit_semaphore(&(s_spi[id].tx_sema));
341		rtos_deinit_semaphore(&(s_spi[id].rx_sema));
342		s_spi[id].id_init_bits &= ~BIT(id);
343	}
