345	static void spi_id_write_bytes_common(spi_id_t id)
346	{
347		for (int i = 0; i < s_spi[id].tx_size; i++) {
348			BK_WHILE (!spi_hal_is_tx_fifo_wr_ready(&s_spi[id].hal));
349			spi_hal_write_byte(&s_spi[id].hal, s_spi[id].tx_buf[i]);
350		}
351	}
352	
353	static uint32_t spi_id_read_bytes_common(spi_id_t id)
354	{
355		uint8_t data = 0;
356		uint32_t offset = s_spi[id].rx_offset;
357	
358		while (spi_hal_read_byte(&s_spi[id].hal, &data) == BK_OK) {
359			if ((s_spi[id].rx_buf) && (offset < s_spi[id].rx_size)) {
360				s_spi[id].rx_buf[offset++] = data;
361			}
362		}
363		s_spi[id].rx_offset = offset;
364		SPI_LOGV("spi offset:%d\r\n", s_spi[id].rx_offset);
365		return offset;
366	}
