488	bk_err_t bk_spi_driver_init(void)
489	{
490		if (s_spi_driver_is_init) {
491			return BK_OK;
492		}
493	
494		spi_int_config_t int_config_table[] = SPI_INT_CONFIG_TABLE;
495		os_memset(&s_spi_rx_isr, 0, sizeof(s_spi_rx_isr));
496		os_memset(&s_spi_tx_finish_isr, 0, sizeof(s_spi_tx_finish_isr));
497		for (int id = SPI_ID_0; id < SPI_ID_MAX; id++) {
498	#if (CONFIG_SPI_PM_CB_SUPPORT)
499			if (id == SPI_ID_0) {
500				//SPI_ID_0 of BK7236 is in AON domain
501			} else if (id == SPI_ID_1) {
502				bk_pm_module_vote_power_ctrl(PM_POWER_SUB_MODULE_NAME_BAKP_SPI1, PM_POWER_MODULE_STATE_ON);
503			}
504	#endif
505			spi_int_config_t *cur_int_cfg = &int_config_table[id];
506			bk_int_isr_register(cur_int_cfg->int_src, cur_int_cfg->isr, NULL);
507			s_spi[id].hal.id = id;
508		}
509		spi_statis_init();
510		s_spi_driver_is_init = true;
511	
512		return BK_OK;
513	}
