516	{
517		if (!s_spi_driver_is_init) {
518			return BK_OK;
519		}
520		spi_int_config_t int_cfg_table[] = SPI_INT_CONFIG_TABLE;
521		for (int id = SPI_ID_0; id < SPI_ID_MAX; id++) {
522			spi_id_deinit_common(id);
523			bk_int_isr_unregister(int_cfg_table[id].int_src);
524	#if (CONFIG_SPI_PM_CB_SUPPORT)
525			if (id == SPI_ID_0) {
526				//SPI_ID_0 of BK7236 is in AON domain
527			} else if (id == SPI_ID_1) {
528				bk_pm_module_vote_power_ctrl(PM_POWER_SUB_MODULE_NAME_BAKP_SPI1, PM_POWER_MODULE_STATE_OFF);
529			}
530	#endif
531		}
532	
533		s_spi_driver_is_init = false;
534	
535		return BK_OK;
536	}
