922	bk_err_t bk_spi_dma_duplex_xfer(spi_id_t id, const void *tx_data, uint32_t tx_size, void *rx_data, uint32_t rx_size)
923	{
924		SPI_RETURN_ON_NOT_INIT();
925		SPI_RETURN_ON_ID_NOT_INIT(id);
926		SPI_RETURN_ON_INVALID_ID(id);
927	
928		if (tx_size != rx_size) {
929			SPI_LOGW("tx and rx size must equal.\r\n");
930			return BK_ERR_SPI_DUPLEX_SIZE_NOT_EQUAL;
931		}
932	
933		uint32_t len = rx_size > 0 ? rx_size : tx_size;
934		uint32_t offset = 0;
935		s_current_spi_dma_wr_id = id;
936		s_current_spi_dma_rd_id = id;
937	
938		while(len > 0) {
939			if(rx_data) {
940				s_spi[id].is_rx_blocked = true;
941				spi_hal_clear_rx_fifo(&s_spi[id].hal);
942				spi_hal_set_rx_trans_len(&s_spi[id].hal, rx_size);
943				bk_dma_set_dest_start_addr(s_spi[id].spi_rx_dma_chan,((uint32_t)rx_data + offset));
944				bk_dma_set_transfer_len(s_spi[id].spi_rx_dma_chan,rx_size);
945			}
946	
947			if(tx_data) {
948				s_spi[id].is_tx_blocked = true;
949				spi_hal_clear_tx_fifo(&s_spi[id].hal);
950				spi_hal_set_tx_trans_len(&s_spi[id].hal, tx_size);
951				bk_dma_set_src_start_addr(s_spi[id].spi_tx_dma_chan,((uint32_t)tx_data + offset));
952				bk_dma_set_transfer_len(s_spi[id].spi_tx_dma_chan,tx_size);
953			}
954			uint32_t int_level = spi_enter_critical();
955			spi_duplex_tx_rx_enable(id);
956			spi_exit_critical(int_level);
957	
958			rtos_get_semaphore(&s_spi[id].tx_sema, BEKEN_NEVER_TIMEOUT);
959			rtos_get_semaphore(&s_spi[id].rx_sema, BEKEN_NEVER_TIMEOUT);
960	
961			int_level = spi_enter_critical();
962			spi_hal_disable_rx(&s_spi[id].hal);
963			spi_hal_disable_tx(&s_spi[id].hal);
964			spi_hal_disable_tx_fifo_int(&s_spi[id].hal);
965			spi_hal_disable_rx_fifo_int(&s_spi[id].hal);
966			extern uint32_t dma_wait_to_idle(dma_id_t id);
967			dma_wait_to_idle(s_spi[id].spi_tx_dma_chan);
968			dma_wait_to_idle(s_spi[id].spi_rx_dma_chan);
969			spi_exit_critical(int_level);
970	
971			len = rx_size > 0 ? (len-rx_size) : (len-tx_size);
972			offset += rx_size > 0 ? (rx_size) : (tx_size);
973		}
974	
975		return BK_OK;
976	}
