1083	static void spi_isr_common(spi_id_t id)
1084	{
1085		spi_hal_t *hal = &s_spi[id].hal;
1086		uint8_t rd_data = 0;
1087		uint32_t int_status = 0;
1088		uint32_t rd_offset = s_spi[id].rx_offset;
1089		SPI_STATIS_DEC();
1090		SPI_STATIS_GET(spi_statis, id);
1091	
1092		int_status = spi_hal_get_interrupt_status(hal);
1093		spi_hal_clear_interrupt_status(hal, int_status);
1094	
1095		SPI_LOGV("int_status:%x\r\n", int_status);
1096	
1097		if (spi_hal_is_rx_fifo_int_triggered_with_status(hal, int_status)) {
1098			SPI_STATIS_INC(spi_statis->rx_fifo_isr_cnt);
1099			SPI_LOGV("rx fifo int triggered\r\n");
1100			spi_id_read_bytes_common(id);
1101			if (s_spi_rx_isr[id].callback) {
1102				s_spi_rx_isr[id].callback(id, s_spi_rx_isr[id].param);
1103			}
1104		}
1105	
1106		if (spi_hal_is_rx_finish_int_triggered(hal, int_status)) {
1107			SPI_STATIS_INC(spi_statis->rx_finish_isr_cnt);
1108			SPI_LOGV("rx fifo finish int triggered\r\n");
1109			if (s_spi[id].rx_size && s_spi[id].rx_buf) {
1110				while (spi_hal_read_byte(hal, &rd_data) == BK_OK) {
1111					if (rd_offset < s_spi[id].rx_size) {
1112						s_spi[id].rx_buf[rd_offset++] = rd_data;
1113					}
1114				}
1115				s_spi[id].rx_offset = rd_offset;
1116			}
1117			bk_spi_clr_rx(id);
1118			if (s_spi_rx_finish_isr[id].callback){
1119				s_spi_rx_finish_isr[id].callback(s_current_spi_dma_rd_id,s_spi_rx_finish_isr[id].param);
1120			}
1121			if (s_spi[id].is_rx_blocked) {
1122				rtos_set_semaphore(&s_spi[id].rx_sema);
1123				s_spi[id].is_rx_blocked = false;
1124			}
