/* spi_clk(more than 1M) support list when source_clk = XTAL_26M
 * sort the numbers from largest to smallest, otherwize binary_search will not work
 */
static const uint32_t s_spi_clk_list[] = {
	26000000, /**< DIV1 */
	13000000, /**< DIV2 */
	6500000,  /**< DIV4 */
	5200000,  /**< DIV5 */
	3250000,  /**< DIV8 */
	2600000,  /**< DIV10 */
