249	static int bk7258_power_gate(uint32_t mask, bool enable)
250	{
251	  irqstate_t flags;
252	  int ret;
253	
254	  /* The Armino register is low-active: 1 means power down. */
255	
256	  flags = enter_critical_section();
257	  modifyreg32(BK7258_SYS_POWER_WAKEUP, mask, enable ? 0 : mask);
258	  ret = ((getreg32(BK7258_SYS_POWER_WAKEUP) & mask) == 0) == enable ?
259	        OK : -EIO;
260	  leave_critical_section(flags);
261	
262	  /* Errors only: the read-back check above is the useful part, and the SARADC
263	   * sampler power-gates its domain on every cycle, so logging every success
264	   * drowned the capture. */
265	
266	  if (ret < 0)
267	    {
268	      syslog(LOG_ERR,
269	             "[BK7258] power gate mask=0x%08lx enable=%d ret=%d reg=0x%08lx\n",
270	             (unsigned long)mask, enable, ret,
271	             (unsigned long)getreg32(BK7258_SYS_POWER_WAKEUP));
272	    }
273	
274	  return ret;
275	}
