  /* CONFIG_NSH_ARCHINIT calls this from the NSH startup path. */
  up_putc('N');

#if defined(CONFIG_LCD_JD9853) || defined(CONFIG_LCD_GC9D01)
  int ret;

  ret = board_lcd_initialize();
  if (ret < 0)
